-- KAI pgAdmin production migration packet: 01V verification after 01 (P1 downstream recovery state)
-- READ-ONLY. One SELECT statement; it changes nothing and inserts nothing.
-- Proves the migration produced exactly its intended objects; role and vocabulary rules are
-- evaluated by running the live CHECK expressions against literal values (query_to_xml), not by
-- inserting rows. Last row OVERALL must be PASS before the next step.
-- Generated by scripts/kai-sprint2-pgadmin-production-packet-build.js from
--   artifacts/kai-db-reconciliation-2026-09-16/PRODUCTION_KAI_SCHEMA.json (owner pgAdmin capture, 2026-09-16) and
--   KAI_PGADMIN_PRODUCTION_MIGRATION_PACKET/support/expected_post_migration_catalog_pg16.json.
-- Run it in the pgAdmin Query Tool (Execute script, F5). Read the Data Output grid.
WITH
checks(seq, section, check_id, status, expected, observed, detail) AS (
  SELECT 100, 'V01', 'V01.1',
              CASE WHEN (to_regclass('kai.intake_p1_downstream_attempts') IS NOT NULL) AND (SELECT string_agg(problem, '; ' ORDER BY problem) FROM (
        SELECT 'column ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs (' || a.type || CASE WHEN a.not_null THEN ' NOT NULL' ELSE '' END || ' DEFAULT ' || coalesce(a.def, '-') || ')' END AS problem
          FROM (VALUES
      ('organization_id', 'uuid', true, ''),
      ('intake_file_id', 'uuid', true, ''),
      ('file_profile_id', 'uuid', true, ''),
      ('parser_name', 'text', true, ''),
      ('parser_version', 'text', true, ''),
      ('checksum', 'text', true, ''),
      ('stage', 'text', true, ''),
      ('recovery_state', 'text', true, ''),
      ('attempt_count', 'integer', true, ''),
      ('claim_token', 'uuid', false, ''),
      ('claim_expires_at', 'timestamp with time zone', false, ''),
      ('last_attempt_at', 'timestamp with time zone', false, ''),
      ('next_eligible_at', 'timestamp with time zone', false, ''),
      ('last_error_code', 'text', false, ''),
      ('created_at', 'timestamp with time zone', true, 'now()'),
      ('updated_at', 'timestamp with time zone', true, 'now()')
    ) AS e(name, type, not_null, def)
          FULL JOIN (SELECT a.attname::text AS name, regexp_replace(btrim(regexp_replace(regexp_replace(format_type(a.atttypid, a.atttypmod), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS type, a.attnotnull AS not_null,
                            regexp_replace(btrim(regexp_replace(regexp_replace(coalesce(pg_get_expr(d.adbin, d.adrelid), ''), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
                      WHERE a.attrelid = to_regclass('kai.intake_p1_downstream_attempts') AND a.attnum > 0 AND NOT a.attisdropped) a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.type <> e.type OR a.not_null <> e.not_null OR a.def <> e.def
        UNION ALL
        SELECT 'constraint ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs: ' || a.def END
          FROM (VALUES
      ('intake_p1_downstream_attempts_attempt_count_check', 'd591b6cf3c541134d3181a882a5f448c'),
      ('intake_p1_downstream_attempts_checksum_check', '36d2734cb23df5915220616dd4d76ec0'),
      ('intake_p1_downstream_attempts_error_code_check', '359989a2b7c2f66b5d493487e217eeba'),
      ('intake_p1_downstream_attempts_pkey', '50730324f935926ea4a2411b76c4d20a'),
      ('intake_p1_downstream_attempts_profile_fk', 'd48fff752affc1aaeede469667096e78'),
      ('intake_p1_downstream_attempts_stage_check', 'bd8fe98fc8410c1e6982d20354f1edcc'),
      ('intake_p1_downstream_attempts_state_check', 'e853f63a99e10f5ccd5e104095705063'),
      ('intake_p1_downstream_attempts_state_fact_consistency_check', '1c5b8c2d7501b7ad83e630c51cb1ef9b')
    ) AS e(name, md5)
          FULL JOIN (SELECT conname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5, regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_p1_downstream_attempts') AND contype <> 'n') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
        UNION ALL
        SELECT 'index ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs: ' || a.def END
          FROM (VALUES
      ('intake_p1_downstream_attempts_pkey', '3850561b661ac83ab5d9db35fcbf8070'),
      ('ix_intake_p1_downstream_attempts_tenant_file', '139b857314baf3b140cf073dd530e0a6')
    ) AS e(name, md5)
          FULL JOIN (SELECT indexname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5, regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_indexes WHERE schemaname = 'kai' AND tablename = 'intake_p1_downstream_attempts') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
      ) problems) IS NULL THEN 'PASS' ELSE 'FAIL' END, 'kai.intake_p1_downstream_attempts exists with exactly the migration''s columns, constraints and indexes', CASE WHEN (to_regclass('kai.intake_p1_downstream_attempts') IS NOT NULL) THEN coalesce((SELECT string_agg(problem, '; ' ORDER BY problem) FROM (
        SELECT 'column ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs (' || a.type || CASE WHEN a.not_null THEN ' NOT NULL' ELSE '' END || ' DEFAULT ' || coalesce(a.def, '-') || ')' END AS problem
          FROM (VALUES
      ('organization_id', 'uuid', true, ''),
      ('intake_file_id', 'uuid', true, ''),
      ('file_profile_id', 'uuid', true, ''),
      ('parser_name', 'text', true, ''),
      ('parser_version', 'text', true, ''),
      ('checksum', 'text', true, ''),
      ('stage', 'text', true, ''),
      ('recovery_state', 'text', true, ''),
      ('attempt_count', 'integer', true, ''),
      ('claim_token', 'uuid', false, ''),
      ('claim_expires_at', 'timestamp with time zone', false, ''),
      ('last_attempt_at', 'timestamp with time zone', false, ''),
      ('next_eligible_at', 'timestamp with time zone', false, ''),
      ('last_error_code', 'text', false, ''),
      ('created_at', 'timestamp with time zone', true, 'now()'),
      ('updated_at', 'timestamp with time zone', true, 'now()')
    ) AS e(name, type, not_null, def)
          FULL JOIN (SELECT a.attname::text AS name, regexp_replace(btrim(regexp_replace(regexp_replace(format_type(a.atttypid, a.atttypmod), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS type, a.attnotnull AS not_null,
                            regexp_replace(btrim(regexp_replace(regexp_replace(coalesce(pg_get_expr(d.adbin, d.adrelid), ''), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
                      WHERE a.attrelid = to_regclass('kai.intake_p1_downstream_attempts') AND a.attnum > 0 AND NOT a.attisdropped) a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.type <> e.type OR a.not_null <> e.not_null OR a.def <> e.def
        UNION ALL
        SELECT 'constraint ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs: ' || a.def END
          FROM (VALUES
      ('intake_p1_downstream_attempts_attempt_count_check', 'd591b6cf3c541134d3181a882a5f448c'),
      ('intake_p1_downstream_attempts_checksum_check', '36d2734cb23df5915220616dd4d76ec0'),
      ('intake_p1_downstream_attempts_error_code_check', '359989a2b7c2f66b5d493487e217eeba'),
      ('intake_p1_downstream_attempts_pkey', '50730324f935926ea4a2411b76c4d20a'),
      ('intake_p1_downstream_attempts_profile_fk', 'd48fff752affc1aaeede469667096e78'),
      ('intake_p1_downstream_attempts_stage_check', 'bd8fe98fc8410c1e6982d20354f1edcc'),
      ('intake_p1_downstream_attempts_state_check', 'e853f63a99e10f5ccd5e104095705063'),
      ('intake_p1_downstream_attempts_state_fact_consistency_check', '1c5b8c2d7501b7ad83e630c51cb1ef9b')
    ) AS e(name, md5)
          FULL JOIN (SELECT conname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5, regexp_replace(btrim(regexp_replace(regexp_replace(pg_get_constraintdef(oid, true), '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_constraint WHERE conrelid = to_regclass('kai.intake_p1_downstream_attempts') AND contype <> 'n') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
        UNION ALL
        SELECT 'index ' || coalesce(e.name, a.name) || CASE WHEN e.name IS NULL THEN ' unexpected' WHEN a.name IS NULL THEN ' missing' ELSE ' differs: ' || a.def END
          FROM (VALUES
      ('intake_p1_downstream_attempts_pkey', '3850561b661ac83ab5d9db35fcbf8070'),
      ('ix_intake_p1_downstream_attempts_tenant_file', '139b857314baf3b140cf073dd530e0a6')
    ) AS e(name, md5)
          FULL JOIN (SELECT indexname::text AS name, md5(regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '')) AS md5, regexp_replace(btrim(regexp_replace(regexp_replace(indexdef, '\m(kai|public)\.', '', 'g'), '\s+', ' ', 'g')), ' NOT VALID$', '') AS def
                       FROM pg_indexes WHERE schemaname = 'kai' AND tablename = 'intake_p1_downstream_attempts') a ON a.name = e.name
         WHERE e.name IS NULL OR a.name IS NULL OR a.md5 <> e.md5
      ) problems), 'identical') ELSE 'table absent' END, '16 columns, 9 constraints (incl. the profile foreign key and state/fact consistency CHECK), primary key and tenant/file index'
)
SELECT seq, section, check_id, status, expected, observed, detail FROM checks
UNION ALL
SELECT 999, 'OVERALL', 'OVERALL',
       CASE WHEN EXISTS (SELECT 1 FROM checks WHERE status NOT IN ('PASS', 'INFO', 'WARN')) THEN 'FAIL' ELSE 'PASS' END,
       'every row PASS (migration 01 verified)',
       coalesce('failing rows: ' || (SELECT string_agg(check_id, ', ' ORDER BY seq) FROM checks WHERE status NOT IN ('PASS', 'INFO', 'WARN')), 'all rows PASS')
         || coalesce('; WARN: ' || (SELECT string_agg(check_id, ', ' ORDER BY seq) FROM checks WHERE status = 'WARN'), ''),
       CASE WHEN EXISTS (SELECT 1 FROM checks WHERE status NOT IN ('PASS', 'INFO', 'WARN'))
            THEN 'STOP. Do not run the next file. Export this grid as CSV and send it back.' ELSE 'Verified.' END
ORDER BY seq;
